import { Project } from '../../src'

describe('PropertyAccessExpression infinite recursion (DEF0701649)', () => {
    test('Defect is not reproducible', async () => {
        const project = new Project()

        // Without the fix, this would blow the heap and crash. We don't need
        // to do any additional validation.
        await project
            .addFile({
                path: 'test.js',
                content: `
function demo(another) {
    var data = {}
    data.some = another.some
    return data
}
`,
            })
            .getDiagnostics()
    })

    test('DEF0708752: Fix identifiers that resolves to itself while getting value declaration from crashing the build', async () => {
        const project = new Project()

        // Without the fix, this would blow the heap and crash. We don't need
        // to do any additional validation.
        await project
            .addFile({
                path: 'test.js',
                content: `
var DomainFinderUtil = {
    setErrorCodes: function(exports) {
        exports.errorCodes = {
            DOMAIN_TOO_SHORT: 'Domain name too short.',
        };
    },
    checkFreeExports: function(module, freeExports) {
        if (freeExports) {
            if (module.exports == freeExports) {
                console.log("Free exports");
            }
        }
    }
}
`,
            })
            .getDiagnostics()
    })

    test('Fix does not regress valid use cases', async () => {
        const project = new Project()
        const file = project.addFile({
            path: 'test.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'

const TEST = { hello: 'world' }

Record({
    $id: Now.ID['test'],
    table: 'test',
    data: {
        hello: TEST.hello
    }
})
`,
        })

        const [record] = (await file.getRecords()).query()
        expect(record).toBeDefined()
        expect(record.get('hello').getValue()).toBe('world')
    })
})
